// src/services/schedule/database/students.ts
var pushStudentsLessons = async (group, groupData, date6) => {
  let text3 = await StudentTextBuilder.generateTitleText(group, date6);
  await db2.delete(lessons).where(and(eq(lessons.group, group), eq(lessons.date, date6)));
  for (const lesson in groupData) {
    if (groupData[lesson].length === 1) {
      try {
        text3 += await proccessJoinedLessons(lesson, groupData[lesson], group, date6);
      } catch (e) {
        console.log(`[${group}] \u041E\u0448\u0438\u0431\u043A\u0430 \u043F\u0440\u0438 \u0437\u0430\u043F\u0438\u0441\u0438 \u0441\u043E\u0432\u043C\u0435\u0449\u0435\u043D\u043D\u043E\u0439 \u043F\u0430\u0440\u044B: `, e);
      }
    }
    if (groupData[lesson].length === 2) {
      try {
        text3 += await proccessSubGroupsLessons(lesson, groupData[lesson], group, date6);
      } catch (e) {
        console.log(`[${group}] \u041E\u0448\u0438\u0431\u043A\u0430 \u043F\u0440\u0438 \u0437\u0430\u043F\u0438\u0441\u0438 \u0440\u0430\u0437\u0434\u0435\u043B\u0435\u043D\u043D\u043E\u0439 \u043F\u0430\u0440\u044B: `, e);
      }
    }
  }
  await startStudentSchedule(text3, group, 80, 500);
};
var proccessSubGroupsLessons = async (count, lessonData, group, date6) => {
  let result = "";
  for (let [lesson, subgroup, room, maybeTeacher] of lessonData) {
    let teacherId;
    if (maybeTeacher == "\u041D\u0438\u0447\u0435\u0433\u043E")
      maybeTeacher = null;
    if (maybeTeacher) {
      const teacher = await db2.select().from(teachers).where(eq(teachers.initials, maybeTeacher || null));
      teacherId = teacher.length ? teacher[0].id : null;
    }
    const existLessons = await db2.select().from(lessons).where(and(eq(lessons.count, Number(count)), eq(lessons.group, group), eq(lessons.date, date6), eq(lessons.status, lessonStatus[subgroup] || "Joined"), eq(lessons.room, room || null)));
    if (existLessons[0]) {
      await db2.update(lessons).set({
        count: Number(count),
        date: date6,
        group,
        lesson,
        room: room || null,
        teacher: teacherId || null,
        status: lessonStatus[subgroup] || "Joined"
      }).where(eq(lessons.id, existLessons[0].id));
    } else {
      db2.insert(lessons).values({
        count: Number(count),
        date: date6,
        group,
        lesson,
        room: room || null,
        teacher: teacherId || null,
        status: lessonStatus[subgroup] || "Joined"
      }).catch((e) => console.log(e));
    }
    result += StudentTextBuilder.subgroupLesson(count, lesson, room, subgroup, maybeTeacher || null);
  }
  return result;
};
var proccessJoinedLessons = async (count, lessonData, group, date6) => {
  let teacherId;
  if (!lessonData || lessonData.length === 0)
    return;
  let [lesson, subgroup, room, maybeTeacher] = lessonData[0];
  if (maybeTeacher == "\u041D\u0438\u0447\u0435\u0433\u043E")
    maybeTeacher = null;
  if (maybeTeacher) {
    const teacher = await db2.select().from(teachers).where(eq(teachers.initials, maybeTeacher));
    teacherId = teacher.length ? teacher[0].id : null;
  }
  const existLessons = await db2.select().from(lessons).where(and(eq(lessons.count, Number(count)), eq(lessons.group, group), eq(lessons.date, date6), eq(lessons.lesson, lesson || null), eq(lessons.status, lessonStatus[subgroup] || "Joined"), eq(lessons.room, room || null)));
  if (existLessons[0]) {
    await db2.update(lessons).set({
      count: Number(count),
      date: date6,
      group,
      lesson,
      room: room || null,
      teacher: teacherId || null,
      status: lessonStatus[subgroup] || "Joined"
    }).where(eq(lessons.id, existLessons[0].id));
  } else {
    await db2.insert(lessons).values({
      count: Number(count),
      date: date6,
      group,
      lesson,
      room: room || null,
      teacher: teacherId || null,
      status: lessonStatus[subgroup] || "Joined"
    }).catch((e) => console.log(e));
  }
  return StudentTextBuilder.joinedLesson(count, lesson, room, maybeTeacher || null);
};

