var getLessonInfo = (lesson) => {
  if (lesson.split("_&&").length - 1 == 2) {
    const [group, subgroup, room] = lesson.split("_&&");
    return { group, subgroup, room };
  }
  if (lesson.split("_&&").length - 1 == 1) {
    const [group, room] = lesson.split("_&&");
    return { group, room };
  }
};
var pushTeachersLessons = async (teacherId, teacherData, date6) => {
  let text3 = "";
  for (const lesson in teacherData) {
    const lessonInfo = getLessonInfo(teacherData[lesson]);
    if (!lessonInfo)
      continue;
    const { group, room } = lessonInfo;
    const lessonExist = await db2.select().from(teachers_lessons).where(and(eq(teachers_lessons.teacher, teacherId), eq(teachers_lessons.count, Number(lesson)), eq(teachers_lessons.date, date6), eq(teachers_lessons.room, room), eq(teachers_lessons.group, group)));
    if (!lessonExist[0]) {
      await db2.insert(teachers_lessons).values({
        teacher: teacherId,
        count: Number(lesson),
        date: date6,
        room,
        group
      });
      text3 += TeacherTextBuilder.lesson(String(lesson), group, room);
    }
  }
  return text3;
};

