var compareLessonsStudents = async (group, groupData, date6) => {
  const lessonsLength = Object.values(groupData).flat().length;
  let isNeedEdit = false;
  const groupLessons = await db2.select().from(lessons).where(and(and(eq(lessons.group, group), eq(lessons.date, date6)), or(eq(lessons.status, "Joined"), eq(lessons.status, "SubGroup1"), eq(lessons.status, "SubGroup2"))));
  if (!groupLessons[0] || groupLessons.length != lessonsLength)
    isNeedEdit = true;
  for (const lesson in groupData) {
    const lessonData = groupData[lesson];
    if (Array.isArray(lessonData)) {
      if (lessonData.length === 1) {
        const existsLesson = await db2.select().from(lessons).where(and(eq(lessons.group, group), eq(lessons.status, lessonStatus2[lessonData[0][1]] || "Joined"), eq(lessons.count, Number(lesson)), eq(lessons.date, date6), eq(lessons.lesson, lessonData[0][0])));
        if (!existsLesson[0])
          isNeedEdit = true;
      }
      if (lessonData.length === 2) {
        const existsLesson1 = await db2.select().from(lessons).where(and(eq(lessons.group, group), eq(lessons.status, lessonStatus2[lessonData[0][1]] || "SubGroup1"), eq(lessons.count, Number(lesson)), eq(lessons.date, date6), eq(lessons.room, lessonData[0][2] || null), eq(lessons.lesson, lessonData[0][0])));
        const existsLesson2 = await db2.select().from(lessons).where(and(eq(lessons.group, group), eq(lessons.status, lessonStatus2[lessonData[1][1]] || "SubGroup2"), eq(lessons.count, Number(lesson)), eq(lessons.date, date6), eq(lessons.room, lessonData[1][2] || null), eq(lessons.lesson, lessonData[1][0])));
        if (!existsLesson1[0] || !existsLesson2[0])
          isNeedEdit = true;
      }
    }
  }
  return isNeedEdit;
};

