// src/xlsx/app/main/SaveManager.ts
class SaveManager {
  outputGroup;
  outputTeacher;
  outputEdit;
  isMaxNum;
  constructor(outputGroup, outputTeacher, outputEdit, isMaxNum) {
    this.outputGroup = outputGroup;
    this.outputTeacher = outputTeacher;
    this.outputEdit = outputEdit;
    this.isMaxNum = isMaxNum;
  }
  resultGroup = {};
  resultTeacher = {};
  resultEdit = {};
  isTestJson = true;
  async saveTeacher(data, date6, isSavingTeacher) {
    const empty = new CreateEmptyObjectTeacher(data).create();
    const teacher = new CreateScheduleTeacher(data).create(empty);
    this.resultTeacher = new RecordTeacher().record(teacher);
    this.outputTeacher.push(this.resultTeacher);
    this.outputTeacher = this.outputTeacher.reduce((acc, curr) => ({ ...acc, ...curr }), {});
    if (this.isMaxNum && isSavingTeacher) {
      if (this.isTestJson) {
        new SaveJson(this.outputTeacher).save("\u041F\u0440\u0435\u043F\u043E\u0434\u044B");
      }
      const teachers4 = [];
      for (const teacher2 in this.outputTeacher) {
        teachers4.push({
          initials: teacher2
        });
      }
      await pushTeachers(teachers4);
      await manageScheduleTeachers(this.outputTeacher, date6);
    }
  }
  async saveWeek(data) {
  }
  async saveEdit(data, outputTeacher) {
    const empty = new CreateEmptyObjectEdit(data).create();
    this.resultEdit = new CreateScheduleEdit(data).create(empty);
    if (outputTeacher.length > 1) {
      outputTeacher = outputTeacher.reduce((acc, curr) => ({ ...acc, ...curr }), {});
      this.resultEdit = new MergeObjectEdit(outputTeacher, this.resultEdit).merge();
      this.resultEdit = new FillOfficeEdit().fill(this.resultEdit);
    }
    this.outputEdit.push(this.resultEdit);
    if (this.isMaxNum) {
      if (this.isTestJson) {
        new SaveJson(this.resultEdit).save("\u0417\u0430\u043C\u0435\u043D\u044B");
      }
    }
  }
  async saveGroup(data, outputTeacher, outputEdit, date6) {
    const empty = new CreateEmptyObjectGroup(data).create(new MissingNumbers);
    const group = new CreateGroupData(data).create(new MissingNumbers);
    this.resultGroup = new RecordGroup().record(group, empty);
    this.resultGroup = new RecordNamesForGroup().record(this.resultGroup);
    this.resultGroup = new SeparationGroup().separation(this.resultGroup);
    new RemoveUnnecessary().remove(this.resultGroup);
    this.outputGroup.push(this.resultGroup);
    this.outputGroup = this.outputGroup.reduce((acc, curr) => ({ ...acc, ...curr }), {});
    if (outputTeacher.length > 1) {
      outputTeacher = outputTeacher.reduce((acc, curr) => ({ ...acc, ...curr }), {});
      outputTeacher = new ConvertTeacherInGroup().convert(outputTeacher);
      this.outputGroup = new MergeObjectGroup(outputTeacher, this.outputGroup).merge(this.isMaxNum);
    }
    if (outputEdit.length > 1) {
      outputEdit = outputEdit.reduce((acc, curr) => ({ ...acc, ...curr }), {});
      outputEdit = new ConvertTeacherInGroup().convert(outputEdit);
      this.outputGroup = new MergeObjectGroup(outputEdit, this.outputGroup).merge(this.isMaxNum);
    }
    if (this.isMaxNum) {
      this.outputGroup = new CreateNulls(this.outputGroup).create();
      if (this.isTestJson) {
        new SaveJson(this.outputGroup).save("\u0423\u0447\u0435\u043D\u0438\u043A\u0438");
      }
      await pushGroups(this.groupConvert(this.outputGroup));
      await manageScheduleStudents(this.outputGroup, date6);
    }
  }
  groupConvert(result) {
    const res = [];
    for (const group in result) {
      const match = group.match(/^([\u0410-\u042F\u0430-\u044FA-Za-z]+)(\d+.*)$/);
      if (match && match[1] && match[2]) {
        res.push({
          route: match[1],
          course: match[2]
        });
      }
    }
    return res;
  }
}

// src/xlsx/Start.ts
class Start {
  outputGroup;
  outputTeacher;
  outputEdit;
  constructor(outputGroup, outputTeacher, outputEdit) {
    this.outputGroup = outputGroup;
    this.outputTeacher = outputTeacher;
    this.outputEdit = outputEdit;
  }
  async start(search, date6, isSavingTeacher) {
    const link = new GetLinks().get(search);
    const maxLength = link.length;
    for (let num = 0;num < maxLength; num++) {
      const data = new GetData().get(search, link[num]);
      if (search === "\u043A\u0430\u0431") {
        const isMaxNum = num === maxLength - 1;
        await new SaveManager(this.outputGroup, this.outputTeacher, this.outputEdit, isMaxNum).saveTeacher(data, date6, isSavingTeacher);
      }
      if (search === "\u0440\u0430\u0441") {
        const isMaxNum = num === maxLength - 1;
        await new SaveManager(this.outputGroup, this.outputTeacher, this.outputEdit, isMaxNum).saveWeek(data);
      }
      if (search === "\u0443\u0447\u0435") {
        const isMaxNum = num === maxLength - 1;
        new Start(this.outputGroup, this.outputTeacher, this.outputEdit).start("\u043A\u0430\u0431", date6, isSavingTeacher);
        new Start(this.outputGroup, this.outputTeacher, this.outputEdit).start("\u0437\u0430\u043C", date6, isSavingTeacher);
        await new SaveManager(this.outputGroup, this.outputTeacher, this.outputEdit, isMaxNum).saveGroup(data, this.outputTeacher, this.outputEdit, date6);
      }
      if (search === "\u0437\u0430\u043C") {
        const isMaxNum = num === maxLength - 1;
        new Start(this.outputGroup, this.outputTeacher, this.outputEdit).start("\u043A\u0430\u0431", date6, isSavingTeacher);
        await new SaveManager(this.outputGroup, this.outputTeacher, this.outputEdit, isMaxNum).saveEdit(data, this.outputTeacher);
      }
    }
  }
}

